static unsigned long checks,failures;
#define CHECK(x,s) do{++checks;if(!(x)){++failures;printf("FAIL projectile-create %lu: %s\n",checks,s);}}while(0)
static float number(const BHEntity *e,unsigned long o){float v;memcpy(&v,(const unsigned char*)e+o,4);return v;}
static unsigned long word(const BHEntity *e,unsigned long o){unsigned long v;memcpy(&v,(const unsigned char*)e+o,4);return v;}
static void put(BHEntity *e,unsigned long o,unsigned long v){memcpy((unsigned char*)e+o,&v,4);}
static float data(const BHDrawCommand *d,unsigned int i){float f;memcpy(&f,d->words+i,4);return f;}
static int equal(float a,double b){return fabs((double)a-b)<.00001;}
static void identity(BHMat34 *m){memset(m,0,sizeof(*m));m->m[0][0]=m->m[1][1]=m->m[2][2]=1;}
int __cdecl bh_projectile_create_checkpoint(unsigned long *count){BHEntityPool pool;BHSoundQueue sound;BHDrawQueue queue;BHProjectileLifetime lifetime;BHProjectileDrawContext draw;BHProjectileCreateContext create;BHBallisticProjectileContext ballistic;BHHomingProjectileContext homing;BHScriptParticleContext particles;BHContactEffects contacts;BHFlashFlareContext flash;BHHitMarkerContext markers;BHWorldGeometry world;BHWorldSegmentRoom room;BHWorldSegmentContext segment;BHMathEnvironment fp;
 BHEntity *source,*target,*e,*recycled;BHVec3 p={3,6,9},v={30,60,90};BHSoundResource *resource;BHSoundVoice *voice;BHDrawCommand *d;unsigned long next=77,before,generation,handle;unsigned int i;int expected,actual;BHProjectileQueryState state;long packet[2];
 memset(&ballistic,0,sizeof(ballistic));memset(&homing,0,sizeof(homing));memset(&draw,0,sizeof(draw));memset(&create,0,sizeof(create));memset(&world,0,sizeof(world));memset(&room,0,sizeof(room));memset(&lifetime,0,sizeof(lifetime));memset(&flash,0,sizeof(flash));memset(&markers,0,sizeof(markers));
 CHECK(bh_math_environment_enter(&fp),"PC53");CHECK(bh_entities_init(&pool,20,NULL),"actual pool");CHECK(bh_sound_queue_init(&sound,NULL,NULL,NULL),"actual source sound");CHECK(bh_draw_queue_init(&queue,40,NULL),"actual draw queue");
 source=bh_entity_acquire(&pool);target=bh_entity_acquire(&pool);target->position.x=100;target->position.y=200;target->position.z=300;CHECK(bh_entity_set_query(&pool,target,bh_marker_query),"actual target query");
 world.navigation.next=&world.navigation;world.previous=&world;world.minimum.x=world.minimum.y=world.minimum.z=-1000;world.maximum.x=world.maximum.y=world.maximum.z=1000;world.query_flags=2;identity(&world.transform);identity(&world.inverse);room.world=&world;room.kind=1;
 CHECK(bh_world_segment_init(&segment,&world,1,&room,1,NULL,0,20),"actual empty world segment owner");CHECK(bh_script_particles_init(&particles,&pool,&queue)&&bh_contact_effects_init(&contacts,&pool,&queue,1,2,3,4),"real effect owners");flash.pool=&pool;flash.queue=&queue;markers.pool=&pool;markers.queue=&queue;
 homing.pool=&pool;homing.sound=&sound;homing.segment=&segment;homing.particles=&particles;homing.contacts=&contacts;homing.flash=&flash;homing.markers=&markers;ballistic.bindings=homing;lifetime.pool=&pool;lifetime.sound=&sound;
 for(i=0;i<2;i++){resource=bh_sound_resource_allocate(&sound);CHECK(resource!=NULL,"real source resource");resource->streaming=1;resource->base_frequency=8000;}
 draw.queue=&queue;draw.ballistic_flare=31;draw.ballistic_trail=32;draw.homing_flare=33;draw.homing_trail=34;draw.pulse_image=35;create.lifetime=&lifetime;create.ballistic=&ballistic;create.homing=&homing;create.draw=&draw;create.next_identity=&next;create.loop_sound=0;create.launch_sound=1;
 recycled=bh_entity_acquire(&pool);put(recycled,0x12c,0x12345678);put(recycled,0x134,0xaabbccdd);CHECK(bh_entity_release(&pool,recycled),"prepare actual recycled slot");
 e=bh_projectile_create_ballistic(&create,&world,source,&p,&v,1);CHECK(e==recycled&&next==0&&word(e,0x11c)==77,"constructor acquires real recycled slot and consumes identity once");CHECK(e->step==bh_ballistic_projectile_tick&&e->query==bh_projectile_query&&e->refresh!=NULL,"all installed callbacks have actual source owners");CHECK(!memcmp(&e->position,&p,12)&&!memcmp(&e->origin,&v,12)&&number(e,0xe8)==1,"original pose velocity lifetime");CHECK(word(e,0x124)==(unsigned long)&world&&word(e,0x128)==(unsigned long)source&&word(e,0x130)==(unsigned long)source&&word(e,0x120)==0,"actual owner/cache/source fields");CHECK(word(e,0x12c)==0x12345678&&word(e,0x134)==0xaabbccdd,"constructor preserves original unassigned recycled words");
 CHECK(bh_projectile_query_state(e,&state)&&state.sound!=BH_SOUND_INVALID,"real projectile lifetime view");handle=state.sound;voice=bh_sound_voice(&sound,handle);CHECK(voice&&voice->position.x==3&&voice->velocity.y==60&&voice->frequency==12000,"real constructor loop cue level/pitch/pose");CHECK(sound.voice_count==2,"real launch and loop sounds queued independently");
 e->refresh(e,NULL);CHECK(queue.count==11&&draw.queued==2,"complete installed ballistic refresh queues both producers");d=&queue.commands[9];CHECK(d->kind==BH_DRAW_FLARE&&data(d,3)==2&&data(d,4)==50&&d->words[6]==31,"actual flare fields and image");d=&queue.commands[10];CHECK(d->kind==BH_DRAW_SEGMENT&&d->resource==32&&data(d,0)==4&&data(d,1)==8&&data(d,2)==12&&data(d,3)==2&&data(d,4)==4&&data(d,5)==6,"trail uses forward and backward1/30 endpoints");CHECK(data(d,6)==.3f&&data(d,7)==.3f&&data(d,8)==1&&data(d,9)==1&&d->words[10]==0,"ballistic widths alpha control");
 e->step(e);CHECK(create.ballistic->bindings.error==0&&equal(e->position.x,4)&&equal(e->position.y,8)&&equal(e->position.z,12),"real constructed projectile moves through actual tick/world closure");CHECK(bh_sound_voice(&sound,handle)!=NULL,"real loop stays live after tick");
 packet[0]=20;e->query(e,packet);CHECK(e->step==bh_projectile_cleanup&&e->query==NULL&&e->refresh==NULL,"actual lifetime query schedules cleanup and removes render callback");before=pool.used;e->step(e);CHECK(pool.used==before-1&&!bh_sound_voice(&sound,handle),"actual cleanup stops voice and releases pool slot");
 bh_draw_queue_begin(&queue);next=123;e=bh_projectile_create_homing(&create,&world,source,&p,&v,1,target);CHECK(e&&word(e,0x11c)==123&&next==0&&word(e,0x12c)==(unsigned long)target,"whole homing constructor and identity consumption");CHECK(!memcmp((unsigned char*)e+0x100,&target->position,12)&&word(e,0x118)==BH_SOUND_INVALID,"target sample obtained through actual event3 query and absent-loop sentinel");CHECK(e->step==bh_homing_projectile_tick&&e->query==bh_projectile_query,"real homing owner callbacks");
 srand(19);expected=rand();actual=rand();srand(19);e->refresh(e,NULL);CHECK(rand()==actual&&draw.random_calls==1,"homing render consumes exactly one shared random draw");CHECK(queue.count==12,"homing whole refresh emits flare trail and billboard");d=&queue.commands[10];CHECK(d->kind==BH_DRAW_SEGMENT&&d->resource==34&&data(d,6)==.5f&&data(d,7)==.5f,"homing trail fields");d=&queue.commands[11];CHECK(d->kind==BH_DRAW_BILLBOARD&&d->resource==34&&data(d,0)==4&&data(d,3)==1.5f&&data(d,4)==1.5f&&equal(data(d,5),(double)expected/4096)&&data(d,6)==1&&d->words[7]==0,"real homing billboard arguments");
 packet[0]=17;packet[1]=(long)target;e->query(e,packet);CHECK(word(e,0x12c)==0,"actual removal receiver clears target");put(e,0xe8,0);generation=e->generation;e->step(e);CHECK(e->generation==generation+1,"real constructed homing expiry retires entity");
 recycled=bh_entity_acquire(&pool);put(recycled,0x100,0x3f800000);put(recycled,0x104,0x40000000);put(recycled,0x108,0x40400000);bh_entity_release(&pool,recycled);e=bh_projectile_create_homing(&create,&world,source,&p,&v,1,NULL);CHECK(e==recycled&&word(e,0x12c)==0&&number(e,0x100)==1&&number(e,0x104)==2&&number(e,0x108)==3,"NULL target preserves original stale sample fields");
 bh_draw_queue_begin(&queue);put(e,0xec,0x41a00000);put(e,0xe8,0x3f800000);srand(7);expected=rand();actual=rand();srand(7);CHECK(bh_projectile_pulse_draw(&draw,e)==1&&rand()==actual,"whole pulse draw exactly one random call");d=&queue.commands[9];CHECK(d->kind==BH_DRAW_ORIENTED&&d->resource==35&&data(d,0)==3&&data(d,3)==0&&data(d,4)==-1&&data(d,5)==0,"pulse point and up vector");CHECK(data(d,6)==30&&data(d,7)==60&&data(d,8)==90&&data(d,9)==20&&data(d,10)==20&&equal(data(d,11),(double)expected/4096)&&data(d,12)==.5f&&d->words[13]==8,"pulse direction dimensions angle alpha control");
 queue.capacity=9;bh_draw_queue_begin(&queue);before=draw.attempted;srand(2);rand();actual=rand();srand(2);CHECK(bh_projectile_homing_draw(&draw,e)==0&&draw.attempted==before+3&&rand()==actual,"full queue retains all three producer attempts and random consumption");CHECK(bh_projectile_ballistic_draw(&draw,e)==0&&bh_projectile_pulse_draw(&draw,e)==0,"all full-queue producers report drop");queue.capacity=40;
 before=pool.used;next=55;create.draw=NULL;CHECK(!bh_projectile_create_ballistic(&create,&world,source,&p,&v,1)&&pool.used==before&&next==55,"missing real renderer context rejects before allocation/global consumption");create.draw=&draw;
 CHECK(bh_entities_valid(&pool),"real entity rings valid");CHECK(bh_entities_dispose(&pool)&&bh_sound_queue_dispose(&sound)&&bh_draw_queue_dispose(&queue),"actual source owners disposed");bh_math_environment_leave(&fp);if(count)*count+=checks;return !failures;
}
